class DbCapturedImage extends DataClass implements Insertable<DbCapturedImage> {
  final int id;
  final String filePath;
  final String fileName;
  final String fileFormat;
  final int? fileSize;
  final int? sessionId;
  final int? targetId;
  final String frameType;
  final double exposureDuration;
  final int? gain;

  /// What [gain] is: `gain` (a camera's gain number), `iso` (the ISO speed
  /// of a DSLR or mirrorless frame) or `isoListPosition` (a DSLR frame from
  /// before Skotiq recorded ISO speeds, which stored the position in the
  /// camera's ISO list; its ISO is unknown). Null reads as `gain`. See
  /// `GainKind`.
  final String? gainKind;
  final int? offset;
  final int binX;
  final int binY;
  final String? filter;
  final double? sensorTemp;
  final double? coolerPower;
  final double? hfr;
  final int? starCount;
  final double? background;
  final double? noise;
  final double? qualityScore;
  final double? guidingRmsRa;
  final double? guidingRmsDec;
  final double? guidingRmsTotal;
  final double? mountRa;
  final double? mountDec;
  final double? mountAltitude;
  final double? mountAzimuth;
  final String? pierSide;
  final int? focuserPosition;
  final double? focuserTemp;
  final double? rotatorAngle;
  final bool isPlateSolved;
  final double? solvedRa;
  final double? solvedDec;
  final double? solvedRotation;
  final double? solvedPixelScale;
  final DateTime capturedAt;
  final DateTime createdAt;

  /// When this frame was folded into the personal sky atlas (Pillar A), or null
  /// if it has not been folded. The solved-frame fold hook stamps this after a
  /// successful fold and skips re-folding when it is already set, so a duplicate
  /// inbound `updateCapturedImage{isPlateSolved:true}` (plausible in the
  /// master/slave sync architecture) cannot double-count photons.
  final DateTime? atlasFoldedAt;
  final bool isAccepted;
  final String? rejectionReason;
  final String? producingNodeId;
  final String? producingRunId;
  final String? runtimeGrade;
  final double? eccentricity;
