class SequenceRun extends DataClass implements Insertable<SequenceRun> {
  final int id;

  /// FK to sequences table (nullable because the sequence may be deleted)
  final int? sequenceId;

  /// Snapshot of the sequence name at the time of execution
  final String sequenceName;
  final DateTime startedAt;

  /// When the run ended (null if still running)
  final DateTime? endedAt;

  /// A `SequenceRunStatus` token; `running` while in flight.
  final String status;

  /// JSON blob with detailed statistics
  /// Structure: {
  ///   "wallClockSecs": double,
  ///   "integrationSecs": double,
  ///   "overheadSecs": double,
  ///   "framesCaptured": int,
  ///   "framesRejected": int,
  ///   "targetBreakdown": { "targetName": { "filter": { "captured": int, "rejected": int, "integrationSecs": double } } },
  ///   "triggerFires": int,
  ///   "autofocusRuns": int,
  ///   "meridianFlips": int,
  ///   "ditherCount": int,
  ///   "errorMessages": [ "..." ]
  /// }
  final String statsJson;

  /// The exact sequence JSON used for this run, captured at run start.
  ///
  /// Persisting the real snapshot — rather than re-reading the live, possibly
  /// since-edited sequence — lets the run-history "diff vs previous run" view
  /// compare what actually executed on each night. Nullable because legacy
  /// rows (and runs started before this column existed) have no snapshot, and
  /// resumed-from-checkpoint runs may not have a Dart-side sequence to capture.
  final String? sequenceSnapshotJson;
  const SequenceRun({
    required this.id,
    this.sequenceId,
    required this.sequenceName,
    required this.startedAt,
    this.endedAt,
    required this.status,
    required this.statsJson,
    this.sequenceSnapshotJson,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    if (!nullToAbsent || sequenceId != null) {
      map['sequence_id'] = Variable<int>(sequenceId);
    }
    map['sequence_name'] = Variable<String>(sequenceName);
    map['started_at'] = Variable<DateTime>(startedAt);
    if (!nullToAbsent || endedAt != null) {
      map['ended_at'] = Variable<DateTime>(endedAt);
    }
    map['status'] = Variable<String>(status);
    map['stats_json'] = Variable<String>(statsJson);
    if (!nullToAbsent || sequenceSnapshotJson != null) {
      map['sequence_snapshot_json'] = Variable<String>(sequenceSnapshotJson);
    }
    return map;
  }

  SequenceRunsCompanion toCompanion(bool nullToAbsent) {
    return SequenceRunsCompanion(
      id: Value(id),
      sequenceId: sequenceId == null && nullToAbsent
          ? const Value.absent()
          : Value(sequenceId),
      sequenceName: Value(sequenceName),
      startedAt: Value(startedAt),
      endedAt: endedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(endedAt),
      status: Value(status),
      statsJson: Value(statsJson),
      sequenceSnapshotJson: sequenceSnapshotJson == null && nullToAbsent
          ? const Value.absent()
          : Value(sequenceSnapshotJson),
    );
  }

  factory SequenceRun.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return SequenceRun(
      id: serializer.fromJson<int>(json['id']),
      sequenceId: serializer.fromJson<int?>(json['sequenceId']),
      sequenceName: serializer.fromJson<String>(json['sequenceName']),
      startedAt: serializer.fromJson<DateTime>(json['startedAt']),
      endedAt: serializer.fromJson<DateTime?>(json['endedAt']),
      status: serializer.fromJson<String>(json['status']),
      statsJson: serializer.fromJson<String>(json['statsJson']),
      sequenceSnapshotJson: serializer.fromJson<String?>(
        json['sequenceSnapshotJson'],
      ),
    );
