    extends BaseReferences<_$SkotiqDatabase, DarkroomJobs, DarkroomJobRow> {
  $DarkroomJobsReferences(super.$_db, super.$_table, super.$_typedResult);

  static $ImagingSessionsTable _sessionIdTable(_$SkotiqDatabase db) =>
      db.imagingSessions.createAlias(
        $_aliasNameGenerator(db.darkroomJobs.sessionId, db.imagingSessions.id),
      );

  $$ImagingSessionsTableProcessedTableManager? get sessionId {
    final $_column = $_itemColumn<int>('session_id');
    if ($_column == null) return null;
    final manager = $$ImagingSessionsTableTableManager(
      $_db,
      $_db.imagingSessions,
    ).filter((f) => f.id.sqlEquals($_column));
    final item = $_typedResult.readTableOrNull(_sessionIdTable($_db));
    if (item == null) return manager;
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: [item]),
    );
  }

  static MultiTypedResultKey<DeliveryJournal, List<DeliveryJournalRow>>
  _deliveryJournalRefsTable(_$SkotiqDatabase db) =>
      MultiTypedResultKey.fromTable(
        db.deliveryJournal,
        aliasName: $_aliasNameGenerator(
          db.darkroomJobs.id,
          db.deliveryJournal.jobId,
        ),
      );

  $DeliveryJournalProcessedTableManager get deliveryJournalRefs {
    final manager = $DeliveryJournalTableManager(
      $_db,
      $_db.deliveryJournal,
    ).filter((f) => f.jobId.id.sqlEquals($_itemColumn<int>('id')!));

    final cache = $_typedResult.readTableOrNull(
      _deliveryJournalRefsTable($_db),
    );
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: cache),
    );
  }
}

